/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: chosen, readBlob, text, http
 *   Constants: jpeg, png, webp, gif, key
 * Tests
 *   - the type is declared from the signature alone: JPEG, PNG and WebP, never a GIF or a short file
 *   - an empty, oversized or unreadable file is refused before anything is read or sent, and a read of another length is checked again
 *   - a name with an unpaired surrogate is refused as invalid before anything is sent, while any encodable name is kept
 *   - the request is one file part with the encoded name, the detected type and the intent key, and a retry rebuilds identical bytes
 *   - a receipt naming another key is unconfirmed and keeps the intent for Retry
 *   - an upload is posted to its item under the captured viewer, and a response this bundle cannot parse asks for a reload and drops the intent
 *   - refusals map to their message and keep only an unknown outcome
 * @end-catalog */

import { captureAccountOperation } from '../../api/accountEpoch';
import { ApiError } from '../../api/client';
import { adminWorkspace, ADMIN_RELOAD_REQUIRED } from './adminWorkspace';
import { json, viewer } from './adminFixtures.testSupport';
import { catalogCoverUploadRequest, COVER_UPLOAD_CEILING_BYTES, coverUploadRefusal, coverUploadType, readCoverUpload, uploadCatalogCover, type CoverUpload } from './catalogCoverUpload';

/** Synthetic signatures only; no real image or personal file is used. */
const jpeg = [0xff, 0xd8, 0xff, 0xe0, 0, 0x10, 0x4a, 0x46, 0x49, 0x46, 0, 1], png = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 13];
const webp = [...new TextEncoder().encode('RIFF'), 4, 0, 0, 0, ...new TextEncoder().encode('WEBP')], gif = [...new TextEncoder().encode('GIF89a'), 1, 0, 1, 0, 0, 0];
/** jsdom's File has no arrayBuffer, so each file reads through its own. */
const chosen = (bytes: number[], name: string, read?: () => Promise<ArrayBuffer>, size?: number) => {
  const file = new File([Uint8Array.from(bytes)], name, { type: 'image/gif' }), arrayBuffer = vi.fn(read ?? (async () => Uint8Array.from(bytes).buffer));
  Object.defineProperty(file, 'arrayBuffer', { value: arrayBuffer });
  if (size !== undefined) Object.defineProperty(file, 'size', { value: size });
  return { file, arrayBuffer };
};
const readBlob = (blob: Blob) => new Promise<Uint8Array>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(new Uint8Array(reader.result as ArrayBuffer)); reader.onerror = reject; reader.readAsArrayBuffer(blob); });
const text = (bytes: Uint8Array) => new TextDecoder().decode(bytes);
const key = '30000000-0000-4000-8000-000000000003';
const http = (status: number, code?: string) => new ApiError('synthetic', 'http', status, code);

beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin'); });
afterEach(() => { adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('the type is declared from the signature alone: JPEG, PNG and WebP, never a GIF or a short file', async () => {
  expect(coverUploadType(Uint8Array.from(jpeg))).toBe('image/jpeg');
  expect(coverUploadType(Uint8Array.from(png))).toBe('image/png');
  expect(coverUploadType(Uint8Array.from(webp))).toBe('image/webp');
  expect(coverUploadType(Uint8Array.from(gif))).toBeNull();
  expect(coverUploadType(Uint8Array.from(webp.slice(0, 11)))).toBeNull();
  expect(coverUploadType(Uint8Array.from([0xff, 0xd8]))).toBeNull();
  const named = await readCoverUpload(chosen(png, 'cover.jpg').file);
  expect(named).toMatchObject({ type: 'image/png', filename: 'cover.jpg' });
  expect(await readCoverUpload(chosen(gif, 'cover.png').file)).toEqual({ refusal: 'cover.upload_type' });
});

test('an empty, oversized or unreadable file is refused before anything is read or sent, and a read of another length is checked again', async () => {
  expect(await readCoverUpload(chosen([], 'empty.png').file)).toEqual({ refusal: 'cover.upload_invalid' });
  const large = chosen(png, 'large.png', undefined, COVER_UPLOAD_CEILING_BYTES + 1);
  expect(await readCoverUpload(large.file)).toEqual({ refusal: 'cover.upload_too_large' }); expect(large.arrayBuffer).not.toHaveBeenCalled();
  expect(await readCoverUpload(chosen(png, 'gone.png', () => Promise.reject(new DOMException('gone', 'NotReadableError'))).file)).toEqual({ refusal: 'cover.upload_invalid' });
  // The file changed after it was chosen: its read is empty or over the ceiling.
  expect(await readCoverUpload(chosen(png, 'emptied.png', async () => new ArrayBuffer(0)).file)).toEqual({ refusal: 'cover.upload_invalid' });
  const grown = new Uint8Array(COVER_UPLOAD_CEILING_BYTES + 1); grown.set(png);
  expect(await readCoverUpload(chosen(png, 'grown.png', async () => grown.buffer).file)).toEqual({ refusal: 'cover.upload_too_large' });
  const read = await readCoverUpload(chosen(png, 'cover.png').file) as CoverUpload;
  expect(read.bytes.type).toBe('image/png'); expect([...await readBlob(read.bytes)]).toEqual(png);
});

test('a name with an unpaired surrogate is refused as invalid before anything is sent, while any encodable name is kept', async () => {
  // The File constructor replaces unpaired surrogates, so the name a file system may report is set directly.
  const named = (name: string) => { const { file } = chosen(png, 'cover.png'); Object.defineProperty(file, 'name', { value: name }); return file; };
  expect(await readCoverUpload(named('cover\uD800.png'))).toEqual({ refusal: 'cover.upload_invalid' });
  expect(await readCoverUpload(named('\uDC00cover.png'))).toEqual({ refusal: 'cover.upload_invalid' });
  const paired = await readCoverUpload(chosen(png, 'cover \uD83C\uDFB5.png').file) as CoverUpload;
  expect(paired.filename).toBe('cover \uD83C\uDFB5.png'); expect(() => catalogCoverUploadRequest(paired, key)).not.toThrow();
});

test('the request is one file part with the encoded name, the detected type and the intent key, and a retry rebuilds identical bytes', async () => {
  const upload = await readCoverUpload(chosen(webp, "封面 'a' (b)*.png").file) as CoverUpload, first = catalogCoverUploadRequest(upload, key), second = catalogCoverUploadRequest(upload, key);
  expect(first.headers).toEqual({ 'Idempotency-Key': key, 'Content-Type': `multipart/form-data; boundary=FinitudeCover-${key}` });
  expect(first.headers).not.toHaveProperty('If-Match');
  const body = await readBlob(first.body), decoded = text(body);
  expect(decoded.split(`--FinitudeCover-${key}`)).toHaveLength(3);
  expect(decoded).toContain(`Content-Disposition: form-data; name="file"; filename="upload"; filename*=UTF-8''%E5%B0%81%E9%9D%A2%20%27a%27%20%28b%29%2a.png\r\nContent-Type: image/webp\r\n\r\n`);
  expect(decoded.endsWith(`\r\n--FinitudeCover-${key}--\r\n`)).toBe(true);
  expect([...await readBlob(second.body)]).toEqual([...body]);
});

test('a receipt naming another key is unconfirmed and keeps the intent for Retry', async () => {
  const sent: RequestInit[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit) => { sent.push(init); return json({ upload: { id: 'b'.repeat(24) }, receipt: { operationId: '40000000-0000-4000-8000-000000000004' } }); }));
  const upload = await readCoverUpload(chosen(png, 'cover.png').file) as CoverUpload;
  const error = await uploadCatalogCover('album', 'a'.repeat(24), upload, key, adminWorkspace.capture()).catch(caught => caught);
  expect(error).toBeInstanceOf(ApiError); expect(coverUploadRefusal(error)).toEqual({ message: 'cover.upload_unknown', keep: true });
  expect(new Headers(sent[0].headers).get('Idempotency-Key')).toBe(key);
  vi.stubGlobal('fetch', vi.fn(async () => json({ upload: { id: 'b'.repeat(24) }, receipt: { operationId: key } })));
  expect(await uploadCatalogCover('album', 'a'.repeat(24), upload, key, adminWorkspace.capture())).toBe('b'.repeat(24));
});

test('an upload is posted to its item under the captured viewer, and a response this bundle cannot parse asks for a reload and drops the intent', async () => {
  const sent: Array<{ path: string; init: RequestInit }> = [];
  const answer = (value: unknown) => vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => { sent.push({ path, init }); return json(value); }));
  const upload = await readCoverUpload(chosen(png, 'cover.png').file) as CoverUpload;
  answer({ upload: { id: 'b'.repeat(24) }, receipt: { operationId: key } });
  expect(await uploadCatalogCover('artist', 'a'.repeat(24), upload, key, adminWorkspace.capture())).toBe('b'.repeat(24));
  expect([sent[0].path, sent[0].init.method, new Headers(sent[0].init.headers).get('X-Finitude-Account-Viewer')]).toEqual([`/api/admin/v1/catalog/artist/${'a'.repeat(24)}/cover-uploads`, 'POST', viewer]);
  for (const value of [{ upload: { id: 'b'.repeat(24), url: '/staged' }, receipt: { operationId: key } }, { upload: { id: 'B'.repeat(24) }, receipt: { operationId: key } }, { upload: { id: 'b'.repeat(24) } }]) {
    answer(value); expect(coverUploadRefusal(await uploadCatalogCover('artist', 'a'.repeat(24), upload, key, adminWorkspace.capture()).catch(caught => caught))).toEqual({ message: 'common.reload', keep: false });
  }
  expect(adminWorkspace.getSnapshot().reloadRequired).toBe(true);
});

test('refusals map to their message and keep only an unknown outcome', () => {
  const cases: Array<[unknown, string, boolean]> = [
    [new ApiError('reload', 'invalid-response', 200, ADMIN_RELOAD_REQUIRED), 'common.reload', false],
    [new ApiError('offline', 'network'), 'cover.upload_unknown', true], [new ApiError('receipt', 'invalid-response'), 'cover.upload_unknown', true],
    [new DOMException('aborted', 'AbortError'), 'cover.upload_unknown', true], [new TypeError('offline'), 'cover.upload_unknown', true],
    [http(413), 'cover.upload_too_large', false], [http(413, 'ADMIN_CATALOG_COVER_TOO_LARGE'), 'cover.upload_too_large', false],
    [http(429, 'ADMIN_CATALOG_COVER_UPLOAD_LIMIT'), 'cover.upload_limit', false], [http(429), 'cover.upload_busy', true],
    [http(409, 'ADMIN_CATALOG_COVER_UPLOAD_BUSY'), 'cover.upload_unknown', true], [http(409, 'ADMIN_CATALOG_COVER_SOURCE_CHANGED'), 'common.conflict', false],
    [http(409, 'ADMIN_CATALOG_IDEMPOTENCY_CONFLICT'), 'common.conflict', false], [http(400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE'), 'cover.upload_invalid', false],
    [http(503, 'ADMIN_IMPORT_STORAGE_UNAVAILABLE'), 'cover.upload_unavailable', false], [http(503, 'ADMIN_CATALOG_COVER_UNKNOWN'), 'cover.upload_unknown', true],
    [http(500), 'cover.upload_unknown', true], [http(400, 'ADMIN_CATALOG_INVALID_INPUT'), 'common.error', false], [http(400, 'ADMIN_CATALOG_COVER_UNSUPPORTED'), 'common.error', false],
    [http(401), 'common.error', false], [http(403), 'common.error', false], [http(404, 'ADMIN_CATALOG_NOT_FOUND'), 'common.error', false], [http(411), 'common.error', false], [http(422), 'common.error', false]
  ];
  for (const [error, message, keep] of cases) expect(coverUploadRefusal(error)).toEqual({ message, keep });
});
